package com.alibaba.fastjson2;

import com.alibaba.fastjson2.reader.ObjectReader;
import org.junit.jupiter.api.Test;

import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for the new {@link JSON#parseObject(String, Type, JSONReader.Context)} method.
 */
public class JSONParseObjectTypeContextTest {

    @Test
    public void testParseObjectWithTypeAndContext_nullInput() {
        JSONReader.Context context = JSONFactory.createReadContext();
        Type type = User.class;

        assertNull(JSON.parseObject((String) null, type, context));
        assertNull(JSON.parseObject("", type, context));
    }

    @Test
    public void testParseObjectWithTypeAndContext_simpleObject() {
        String json = "{\"name\":\"John\",\"age\":30}";
        Type type = User.class;
        JSONReader.Context context = JSONFactory.createReadContext();

        User user = JSON.parseObject(json, type, context);
        assertNotNull(user);
        assertEquals("John", user.name);
        assertEquals(30, user.age);
    }

    @Test
    public void testParseObjectWithTypeAndContext_genericType() {
        String json = "[{\"name\":\"Alice\",\"age\":25},{\"name\":\"Bob\",\"age\":35}]";
        Type type = new ParameterizedType() {
            @Override
            public Type[] getActualTypeArguments() {
                return new Type[]{User.class};
            }

            @Override
            public Type getRawType() {
                return List.class;
            }

            @Override
            public Type getOwnerType() {
                return null;
            }
        };
        JSONReader.Context context = JSONFactory.createReadContext();

        List<User> users = JSON.parseObject(json, type, context);
        assertNotNull(users);
        assertEquals(2, users.size());
        assertEquals("Alice", users.get(0).name);
        assertEquals(25, users.get(0).age);
        assertEquals("Bob", users.get(1).name);
        assertEquals(35, users.get(1).age);
    }

    @Test
    public void testParseObjectWithTypeAndContext_mapType() {
        String json = "{\"key1\":\"value1\",\"key2\":42}";
        Type type = new ParameterizedType() {
            @Override
            public Type[] getActualTypeArguments() {
                return new Type[]{String.class, Object.class};
            }

            @Override
            public Type getRawType() {
                return Map.class;
            }

            @Override
            public Type getOwnerType() {
                return null;
            }
        };
        JSONReader.Context context = JSONFactory.createReadContext();

        Map<String, Object> map = JSON.parseObject(json, type, context);
        assertNotNull(map);
        assertEquals("value1", map.get("key1"));
        assertEquals(42, map.get("key2"));
    }

    @Test
    public void testParseObjectWithTypeAndContext_customContextFeatures() {
        String json = "{\"name\":\"John\",\"age\":30}";
        Type type = User.class;
        JSONReader.Context context = JSONFactory.createReadContext(JSONReader.Feature.FieldBased);

        User user = JSON.parseObject(json, type, context);
        assertNotNull(user);
        assertEquals("John", user.name);
        assertEquals(30, user.age);
    }

    @Test
    public void testParseObjectWithTypeAndContext_ignoreCheckCloseFeature() {
        String json = "{\"name\":\"John\",\"age\":30}extra";
        Type type = User.class;
        JSONReader.Context context = JSONFactory.createReadContext(JSONReader.Feature.IgnoreCheckClose);

        User user = JSON.parseObject(json, type, context);
        assertNotNull(user);
        assertEquals("John", user.name);
        assertEquals(30, user.age);
    }

    @Test
    public void testParseObjectWithTypeAndContext_inputNotEndException() {
        String json = "{\"name\":\"John\",\"age\":30}extra";
        Type type = User.class;
        JSONReader.Context context = JSONFactory.createReadContext();

        JSONException exception = assertThrows(JSONException.class, () -> {
            JSON.parseObject(json, type, context);
        });
        assertTrue(exception.getMessage().contains("input not end"));
    }

    @Test
    public void testParseObjectWithTypeAndContext_resolveTasks() {
        String json = "[{\"$ref\":\"$.0\",\"name\":\"John\"},{\"name\":\"Jane\"}]";
        Type type = new ParameterizedType() {
            @Override
            public Type[] getActualTypeArguments() {
                return new Type[]{User.class};
            }

            @Override
            public Type getRawType() {
                return List.class;
            }

            @Override
            public Type getOwnerType() {
                return null;
            }
        };
        JSONReader.Context context = JSONFactory.createReadContext(JSONReader.Feature.SupportAutoType);

        List<User> users = JSON.parseObject(json, type, context);
        assertNotNull(users);
        assertEquals(2, users.size());
        assertEquals("John", users.get(0).name);
        assertEquals("Jane", users.get(1).name);
    }

    @Test
    public void testParseObjectWithTypeAndContext_invalidJson() {
        String json = "{\"name\":\"John\",\"age\":";
        Type type = User.class;
        JSONReader.Context context = JSONFactory.createReadContext();

        assertThrows(JSONException.class, () -> {
            JSON.parseObject(json, type, context);
        });
    }

    @Test
    public void testParseObjectWithTypeAndContext_emptyObject() {
        String json = "{}";
        Type type = User.class;
        JSONReader.Context context = JSONFactory.createReadContext();

        User user = JSON.parseObject(json, type, context);
        assertNotNull(user);
        assertNull(user.name);
        assertEquals(0, user.age);
    }

